SELECT period,uniqExact(actor_id) contributors,countIf(repos>1) multi_repo,round(avg(repos),2) avg_repos,quantileExact(0.5)(months) median_months FROM (SELECT if(created_at<'2026-07-01','main','post') period,actor_id,uniqExact(repo_id) repos,uniqExact(toYYYYMM(created_at)) months FROM normalized_community_openrank WHERE platform='AtomGit' AND org_id=5162848 AND created_at>='2025-07-01' AND created_at<'2026-11-01' GROUP BY period,actor_id) GROUP BY period FORMAT JSON